// YoY % from an ascending observation array, k observations back
function yoyFrom(obs, k) {
  if (!obs || obs.length <= k) return null;
  const a = obs[obs.length - 1 - k]?.v, b = obs[obs.length - 1]?.v;
  return a > 0 && b != null ? ((b / a) - 1) * 100 : null;
}

// National average hard construction cost per square foot — the replacement-
// cost yardstick for the $/sq ft map. Curated (verify & update yearly):
// NAHB "Cost of Constructing a Home" 2024 survey — construction cost only
// (excludes the finished lot, financing, overhead and profit). Land is exactly
// what coastal states' premiums over this number represent.
const BUILD_COST_PER_SQFT = { value: 162, asOf: "2024", source: "NAHB Cost of Constructing a Home 2024 (avg $428K / 2,647 sq ft)" };

function choroplethColor(value, min, max, scale) {
  if (value == null || min === max) return "#1e293b";
  const t = Math.max(0, Math.min(1, (value - min) / (max - min)));
  const lerp = (a, b, p) => Math.round(a + (b - a) * p);
  const rgb = (r, g, b) => `rgb(${r},${g},${b})`;
  switch (scale) {
    case "greenRed": return rgb(lerp(34,220,t), lerp(197,38,t), lerp(94,38,t));     // green→red
    case "blue":     return rgb(lerp(30,59,t), lerp(41,130,t), lerp(59,246,t));       // dark→bright blue
    case "green":    return rgb(lerp(30,16,t), lerp(41,185,t), lerp(59,129,t));       // dark→bright green
    case "purple":   return rgb(lerp(49,139,t), lerp(30,92,t), lerp(63,246,t));       // dark→bright purple
    default:         return rgb(lerp(30,59,t), lerp(41,130,t), lerp(59,246,t));
  }
}

